import type { WixDataAsyncRemoveByFilterOptions } from './types'

/**
 * Options builder for async remove-by-filter operations.
 *
 * Use this builder to configure async remove behavior such as hooks suppression.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataAsyncRemoveByFilterOptionsBuilder {
  /**
   * Sets whether to suppress async remove hooks.
   *
   * When `true`, the async remove runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataAsyncRemoveByFilterOptionsBuilder
  /**
   * Sets whether to include draft items when removing items asynchronously.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataAsyncRemoveByFilterOptionsBuilder
  /**
   * Builds the async remove by filter options object.
   */
  build(): WixDataAsyncRemoveByFilterOptions
}

class WixDataAsyncRemoveByFilterOptionsBuilderImpl
  implements WixDataAsyncRemoveByFilterOptionsBuilder
{
  constructor(
    private readonly options: WixDataAsyncRemoveByFilterOptions = {}
  ) {}

  withSuppressHooks(value: boolean): WixDataAsyncRemoveByFilterOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataAsyncRemoveByFilterOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  build(): WixDataAsyncRemoveByFilterOptions {
    return {
      ...this.options,
    }
  }

  private copy(
    options: WixDataAsyncRemoveByFilterOptions
  ): WixDataAsyncRemoveByFilterOptionsBuilder {
    return new WixDataAsyncRemoveByFilterOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new async remove-by-filter options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create an async remove-by-filter options builder"
 * import { items, AsyncRemoveByFilterOptionsBuilder } from '@wix/data'
 *
 * const options = AsyncRemoveByFilterOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .build()
 *
 * const job = await items.asyncRemoveByFilter(
 *   'myCollection',
 *   { archived: true },
 *   options
 * )
 * ```
 */
export const AsyncRemoveByFilterOptionsBuilder: () => WixDataAsyncRemoveByFilterOptionsBuilder =
  () => new WixDataAsyncRemoveByFilterOptionsBuilderImpl()
